        try c.Deposit{value: depositAmount}() {} catch { return; }
        uint contractBalanceBefore = address(c).balance;
        try c.Collect(collectAmount) {
            // call completed without reverting
        } catch {
            // call reverted
        }
        assertTrue(address(c).balance <= contractBalanceBefore);
    }

